import React from "react";

const Blog = () => {
  return (
    <div className="max-w-7xl mx-auto px-4 py-12">
      <div className="bg-white rounded-xl shadow-md p-8 border border-slate-200">
        <h1 className="text-3xl font-extrabold text-[#304b62] mb-4">
          Success Mentor Educational Blog
        </h1>
        <p className="text-slate-600">
          Articles, exam tips, and learning strategies for Class 1 to 10 students.
        </p>
      </div>
    </div>
  );
};

export default Blog;
